import React from "react";

const FigmaDesign = () => {
  return (
    <div
      style={{
        position: "relative",
        width: "1409px",
        height: "737px",
        background: "#FFFFFF",
        margin: "0 auto", // Ortalamak için
      }}
    >
      {/* Frame 1321317616 */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          padding: "0px",
          gap: "4px",
          position: "absolute",
          width: "1024px",
          height: "394.42px",
          left: "208px",
          top: "136px",
        }}
      >
        {/* Frame 1321317613 */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            justifyContent: "space-between",
            alignItems: "flex-start",
            padding: "0px",
            gap: "851px",
            width: "1024px",
            height: "17.42px",
          }}
        >
          {/* shape-dots 1 */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
              padding: "0px",
              gap: "10px",
              width: "30.16px",
              height: "11.11px",
            }}
          >
            <div
              style={{
                width: "30.16px",
                height: "11.11px",
                background: "#293349",
              }}
            ></div>
          </div>

          {/* kesik-yan-cizgi 1 */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
              padding: "0px",
              gap: "10px",
              width: "143px",
              height: "17.42px",
            }}
          >
            <div
              style={{
                width: "142.57px",
                height: "17.42px",
                background: "#293349",
              }}
            ></div>
          </div>
        </div>

        {/* Frame 1321317615 */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            justifyContent: "center",
            alignItems: "flex-start",
            padding: "0px",
            gap: "4px",
            width: "1024px",
            height: "373px",
          }}
        >
          {/* shape-dots 2 */}
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              padding: "0px",
              width: "11.11px",
              height: "30.95px",
            }}
          >
            <div
              style={{
                width: "11.11px",
                height: "30.95px",
                background: "#293349",
              }}
            ></div>
          </div>

          {/* Frame 1321317614 */}
          <div
            style={{
              boxSizing: "border-box",
              width: "987.46px",
              height: "373px",
              background: "#293349",
              borderWidth: "0px 15px 15px 0px",
              borderStyle: "solid",
              borderColor: "#00C26D",
            }}
          ></div>

          {/* kesik-yan-cizgi 2 */}
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              padding: "20px 0px",
              width: "17.43px",
              height: "140.79px",
            }}
          >
            <div
              style={{
                width: "17.43px",
                height: "100.79px",
                background: "#293349",
              }}
            ></div>
          </div>
        </div>
      </div>

      {/* Frame 1321317622 */}
      <div
        style={{
          position: "absolute",
          width: "1409px",
          height: "178px",
          left: "0px",
          top: "559px",
          background: "#293349",
        }}
      ></div>
    </div>
  );
};

export default EventsSlider;
